"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type PressBloomProps = React.ButtonHTMLAttributes<HTMLButtonElement> & {
  label?: string;
};

/**
 * Primary CTA that blooms concentric rings on press — tactile feedback without
 * shipping a generic Button primitive API.
 */
function PressBloom({
  className,
  label = "Launch",
  children,
  onPointerDown,
  ...props
}: PressBloomProps) {
  const [blooms, setBlooms] = React.useState<{ id: number; x: number; y: number }[]>(
    [],
  );

  const handleDown = (e: React.PointerEvent<HTMLButtonElement>) => {
    onPointerDown?.(e);
    const r = e.currentTarget.getBoundingClientRect();
    const id = Date.now();
    setBlooms((prev) => [
      ...prev,
      { id, x: e.clientX - r.left, y: e.clientY - r.top },
    ]);
    window.setTimeout(() => {
      setBlooms((prev) => prev.filter((b) => b.id !== id));
    }, 700);
  };

  return (
    <button
      type="button"
      onPointerDown={handleDown}
      className={cn(
        "relative inline-flex h-11 items-center justify-center overflow-hidden rounded-full bg-primary px-6 text-sm font-medium text-primary-foreground shadow-[var(--shadow-soft)] transition-transform active:scale-[0.97]",
        className,
      )}
      {...props}
    >
      {blooms.map((b) => (
        <span
          key={b.id}
          aria-hidden
          className="pointer-events-none absolute size-24 -translate-x-1/2 -translate-y-1/2 rounded-full border border-primary-foreground/50 animate-[joy-bloom_0.7s_cubic-bezier(0.22,1,0.36,1)_forwards]"
          style={{ left: b.x, top: b.y }}
        />
      ))}
      <span className="relative z-[1]">{children ?? label}</span>
    </button>
  );
}

export { PressBloom };
